    getCode: function(code, store) {
        var codeStore = Ext.StoreMgr.get('CodeStore'),
                items = codeStore.getData().items;

        for (var i = 0, l = items.length; i < l; i++) {
            if (code === items[i].data.code) {
                var children = items[i].data.children;
                for (var j = 0, l2 = children.length; j < l2; j++) {
                    store.add({
                        text : children[j].text,
                        value : children[j].value
                    });
                }
            }
        }

        return store;
    },

    /* 현재 근무지 정보 조회 */
    onSelect: function() {
        var me = this,
            refs = me.getReferences(),
            vm = me.getViewModel();

        var params = {
            hrHrpmEmpId : refs.hrHrpmEmpId.getValue(),
            stcd: refs.stcd.getValue(),
            crtDt: DateUtils.getDate(new Date()),
            wkplcDvcd: Constants.wkplcDvcd.MAIN_WKPLC
        };

        var wplInfoForm = refs.wplInfoForm;
        Ext.Ajax.request({
            headers: {
                serviceId: 'HwmWplSvc.findOneHwmWplInfo',
                viewId: 'HwmWplAply02M'
            },
            scope : me,
            jsonData :params,
            success : function(res) {
                var result = JSON.parse(res.responseText).result,
                    wkplcNm = refs.wkplcNm,
                    strdt = refs.strdt,
                    edt = refs.edt,
                    hrWrkmWkplcId = refs.hrWrkmWkplcId,
                    wkplcDvcd = refs.wkplcDvcd,
                    hrWrkmEmpWkplcId = refs.hrWrkmEmpWkplcId;
                if(result){
                    var strdtTmp = result.strdt,
                        edtTmp = result.edt;
                    hrWrkmWkplcId.setValue(result.hrWrkmWkplcId);
                    wkplcDvcd.setValue(result.wkplcDvcd);
                    wkplcNm.setValue(result.wkplcNm);
                    strdt.setValue(strdtTmp.substr(0,4)+"-"+strdtTmp.substr(4,2)+"-"+strdtTmp.substr(6,2));
                    edt.setValue(edtTmp.substr(0,4)+"-"+edtTmp.substr(4,2)+"-"+edtTmp.substr(6,2));
                    hrWrkmEmpWkplcId.setValue(result.hrWrkmEmpWkplcId);
                }
                else{
                    hrWrkmWkplcId.setValue(Constants.wkplcId.EMPTY_WKPLC); 		//근무지ID:근무지없음(0)
                    wkplcDvcd.setValue(Constants.wkplcDvcd.MAIN_WKPLC); 		//근무지구분코드:근무지(10)
                    wkplcNm.setValue("근무지없음"); 								 //근무지명:근무지없음
                    strdt.setValue(Ext.Date.format(new Date(), 'Y-m-d')); 		//근무시작일자
                    edt.setValue("2999-12-31"); 								//근무종료일자
                }
                me.redrawAplField();
            }
        });
    },

    /* 신청구분 :: 각 구분코드에 맞게 '변경 후' 필드 초기화 */
    redrawAplField: function() {
        var me = this,
            refs = me.getReferences(),
            bfrStrdt = refs.strdt.getValue(),
            bfrEdt = refs.edt.getValue(),
            wplcAplDvcd = refs.wplcAplDvcd;

        if(!refs.hrWrkmWkplcId.getValue() || wplcAplDvcd.getValue() == null){
            return;
        }

        if(wplcAplDvcd.getValue() === Constants.wplcAplDvcd.WK_PLC){ //근무지변경(01)
              refs.btnFindWkplc.setHidden(false);
              refs.aplStrdt.setEditable(true);
              refs.aplStrdt.setDisabled(false);
              refs.aplStrdt.setValue(null);

              refs.aplWkplcDvcd.setValue(null);
              refs.aplHrWrkmWkplcId.setValue(null);
              refs.aplWkplcNm.setValue(null);

              //근무지 없음 상태일 때는 aplStrdt = bfrStrdt
              if(refs.hrWrkmWkplcId.getValue() == "0") {
                refs.aplStrdt.setMinDate(bfrStrdt);
                refs.aplStrdt.setMaxDate(bfrStrdt);
              }
              else if(DateUtils.getDate(bfrEdt) < DateUtils.getDate(new Date())){ //bfrEdt < 오늘
                refs.aplStrdt.setMinDate(new Date(bfrEdt.getFullYear(), bfrEdt.getMonth(), bfrEdt.getDate() + 1));
                refs.aplStrdt.setMaxDate(new Date());
              }
              else { //bfrEdt >= 오늘
                refs.aplStrdt.setMinDate(new Date());
                refs.aplStrdt.setMaxDate(new Date(bfrEdt.getFullYear(), bfrEdt.getMonth(), bfrEdt.getDate() + 1));
              }
            }
            else { //근무일자변경(02)

              //근무지없음 상태인 경우 근무일자 변경 불가
              if(refs.hrWrkmWkplcId.getValue() == Constants.wkplcId.EMPTY_WKPLC){
                Ext.Msg.show({
                    title : "안내",
                    message : "현재 정보로는 근무지변경만 가능합니다.",
                    fn : function() {
                        refs.wplcAplDvcd.setValue(Constants.wplcAplDvcd.WK_PLC);
                    }});
                return;
              }

                refs.btnFindWkplc.setHidden(true);
                refs.aplStrdt.setEditable(false);
                refs.aplStrdt.setDisabled(true);

                refs.aplWkplcDvcd.setValue(refs.wkplcDvcd.getValue());
                refs.aplHrWrkmWkplcId.setValue(refs.hrWrkmWkplcId.getValue());
                refs.aplWkplcNm.setValue(refs.wkplcNm.getValue());

                refs.aplStrdt.setMinDate(refs.strdt.getValue());
                refs.aplStrdt.setValue(refs.strdt.getValue());

                //aplStrdt에 event listener가 설정 되어 있기 때문에
                //aplEdt에 대한 변경은 해당 순서를 유지해야함.
                refs.aplEdt.setMinDate(new Date());
            }

            refs.aplEdt.setValue(null);
            refs.rmrkCntn.setValue("프로젝트명 : \r\n사유 : ");
    },

