    /* 변경 근무시작일자 체크 */
    onAplStrdtDatefieldChange: function(datefield, newDate, oldDate, eOpts) {
        var refs = this.getReferences(),
            aplStrdt = refs.aplStrdt;

        if (aplStrdt.getValue() == null) {
            return;
        }

        var val = aplStrdt.getValue();
        if (aplStrdt.getMinDate() != null && aplStrdt.getMaxDate() != null) {
            var min = aplStrdt.getMinDate(),
                max = aplStrdt.getMaxDate();

            if (val < min || val > max) {
                Ext.Msg.alert("알림", "근무시작일은\n" + Ext.Date.format(min,'Y-m-d') + " ~ " + Ext.Date.format(max,'Y-m-d') + "\n만 선택가능합니다.");
                aplStrdt.setValue(null);
            }
        }

        //종료일자를 시작일자 이후로 선택하도록 제한
        refs.aplEdt.setMinDate(val);

        // refs.frmDetail.validate();
    },

    /* 변경 근무종료일자 체크 */
    onAplEdtDatefieldChange: function(datefield, newDate, oldDate, eOpts) {
        var refs = this.getReferences(),
            aplStrdt = refs.aplStrdt,
            aplEdt = refs.aplEdt;

        if (aplEdt.getValue() == null) {
            return;
        }

        var val = aplEdt.getValue();
        if (aplEdt.getMinDate() != null) {
            var min = aplEdt.getMinDate();
            if (val < min) {
                Ext.Msg.alert("알림", "근무종료일은\n" + Ext.Date.format(min,'Y-m-d') + "\n부터 선택가능합니다.");
                aplEdt.setValue(null);
            }
        }
    },

    /* 계속 사용 */
    onCheckboxChange: function(checkbox, newValue, oldValue, eOpts) {
        var aplEdt = this.getReferences().aplEdt;
        if (checkbox.getChecked()) {
            aplEdt.setValue('2999-12-31');
            aplEdt.setDisabled(true);
        } else {
            aplEdt.setValue(null);
            aplEdt.setDisabled(false);
        }
    },

